const rules = {
  value: { title: '优质价值候选池', description: '低估值 · 高回报 · 财务稳健', count: 47, conditions: [{ label: '市盈率（PE-TTM）', operator: '小于', value: '15' }, { label: '净资产收益率（ROE）', operator: '大于等于', value: '15%' }, { label: '资产负债率', operator: '小于', value: '55%' }] },
